def find_image(filename):
    """Ищет изображение в известных каталогах. Возвращает путь или None."""
    if not filename:
        return None
    for d in IMAGE_DIRS:
        candidate = os.path.join(d, filename)
        if os.path.exists(candidate):
            return candidate
    return None


# --------------------------------------------------------------------------
# Базовое оформление по ГОСТ
# --------------------------------------------------------------------------
def setup_styles(document):
    style = document.styles["Normal"]
    font = style.font
    font.name = "Times New Roman"
    font.size = Pt(14)
    rpr = style.element.get_or_add_rPr()
    rfonts = rpr.get_or_add_rFonts()
    rfonts.set(qn("w:ascii"), "Times New Roman")
    rfonts.set(qn("w:hAnsi"), "Times New Roman")
    rfonts.set(qn("w:cs"), "Times New Roman")

    pf = style.paragraph_format
    pf.line_spacing_rule = WD_LINE_SPACING.ONE_POINT_FIVE
    pf.space_after = Pt(0)
    pf.space_before = Pt(0)
    pf.first_line_indent = Cm(1.25)
    pf.alignment = WD_ALIGN_PARAGRAPH.JUSTIFY

    # Заголовки
    for name, size in (("Heading 1", 16), ("Heading 2", 14)):
        try:
            h = document.styles[name]
        except KeyError:
            continue
        h.font.name = "Times New Roman"
        h.font.size = Pt(size)
        h.font.bold = True
        h.font.color.rgb = RGBColor(0, 0, 0)
        hrpr = h.element.get_or_add_rPr()
        hrfonts = hrpr.get_or_add_rFonts()
        hrfonts.set(qn("w:ascii"), "Times New Roman")
        hrfonts.set(qn("w:hAnsi"), "Times New Roman")
        hrfonts.set(qn("w:cs"), "Times New Roman")
        hpf = h.paragraph_format
        hpf.space_before = Pt(12)
        hpf.space_after = Pt(6)
        hpf.line_spacing_rule = WD_LINE_SPACING.ONE_POINT_FIVE
        hpf.first_line_indent = Cm(0)
        hpf.keep_with_next = True


def setup_page(document):
    section = document.sections[0]
    section.left_margin = Mm(30)
    section.right_margin = Mm(10)
    section.top_margin = Mm(20)
    section.bottom_margin = Mm(20)
    section.different_first_page_header_footer = True


# --------------------------------------------------------------------------
# Колонтитул с номером страницы (центр), кроме первой страницы
# --------------------------------------------------------------------------
def add_page_number_footer(document):
    section = document.sections[0]
    section.different_first_page_header_footer = True

    # Пустой колонтитул первой страницы (титульный лист без номера)
    first = section.first_page_footer
    if first.paragraphs:
        first.paragraphs[0].text = ""

    footer = section.footer
    p = footer.paragraphs[0] if footer.paragraphs else footer.add_paragraph()
    p.alignment = WD_ALIGN_PARAGRAPH.CENTER
    p.paragraph_format.first_line_indent = Cm(0)

    run = p.add_run()
    fld_begin = OxmlElement("w:fldChar")
    fld_begin.set(qn("w:fldCharType"), "begin")
    instr = OxmlElement("w:instrText")
    instr.set(qn("xml:space"), "preserve")
    instr.text = "PAGE"
    fld_end = OxmlElement("w:fldChar")
    fld_end.set(qn("w:fldCharType"), "end")
    run._r.append(fld_begin)
    run._r.append(instr)
    run._r.append(fld_end)
    _set_run_font(run)


def _set_run_font(run, size=14, bold=False):
    run.font.name = "Times New Roman"
    run.font.size = Pt(size)
    run.font.bold = bold
    rpr = run._r.get_or_add_rPr()
    rfonts = rpr.get_or_add_rFonts()
    rfonts.set(qn("w:ascii"), "Times New Roman")
    rfonts.set(qn("w:hAnsi"), "Times New Roman")
    rfonts.set(qn("w:cs"), "Times New Roman")


# --------------------------------------------------------------------------
# Базовые блоки документа
# --------------------------------------------------------------------------
def add_page_break(document):
    document.add_page_break()


def add_body(document, text):
    p = document.add_paragraph(text)
    p.style = document.styles["Normal"]
    p.alignment = WD_ALIGN_PARAGRAPH.JUSTIFY
    p.paragraph_format.first_line_indent = Cm(1.25)
    return p


def add_code(document, text):
    p = document.add_paragraph()
    p.paragraph_format.first_line_indent = Cm(0)
    p.alignment = WD_ALIGN_PARAGRAPH.LEFT
    run = p.add_run(text)
    run.font.name = "Courier New"
    run.font.size = Pt(12)
    rpr = run._r.get_or_add_rPr()
    rfonts = rpr.get_or_add_rFonts()
    rfonts.set(qn("w:ascii"), "Courier New")
    rfonts.set(qn("w:hAnsi"), "Courier New")
    rfonts.set(qn("w:cs"), "Courier New")
    return p


def add_h1(document, text):
    p = document.add_heading(level=1)
    p.alignment = WD_ALIGN_PARAGRAPH.CENTER
    p.paragraph_format.first_line_indent = Cm(0)
    run = p.add_run(text)
    return p


def add_h2(document, text):
    p = document.add_heading(level=2)
    p.alignment = WD_ALIGN_PARAGRAPH.LEFT
    p.paragraph_format.first_line_indent = Cm(0)
    run = p.add_run(text)
    return p


def add_figure(document, filename, caption):
    """Вставляет изображение (если найдено) и подпись по центру.
    Если изображение не найдено — добавляет место для рисунка и подпись."""
    path = find_image(filename)
    if path:
        try:
            pic_p = document.add_paragraph()
            pic_p.alignment = WD_ALIGN_PARAGRAPH.CENTER
            pic_p.paragraph_format.first_line_indent = Cm(0)
            run = pic_p.add_run()
            run.add_picture(path, width=Cm(15))
        except Exception as exc:  # noqa: BLE001
            ph = document.add_paragraph("[ Не удалось вставить изображение: %s (%s) ]" % (filename, exc))
            ph.alignment = WD_ALIGN_PARAGRAPH.CENTER
            ph.paragraph_format.first_line_indent = Cm(0)
    else:
        ph = document.add_paragraph("[ Здесь вставьте рисунок: %s ]" % (filename or "скриншот"))
        ph.alignment = WD_ALIGN_PARAGRAPH.CENTER
        ph.paragraph_format.first_line_indent = Cm(0)

    cap = document.add_paragraph()
    cap.alignment = WD_ALIGN_PARAGRAPH.CENTER
    cap.paragraph_format.first_line_indent = Cm(0)
    run = cap.add_run(caption)
    run.font.name = "Times New Roman"
    run.font.size = Pt(14)
    return cap


def add_table(document, rows):
    """rows — список списков ячеек."""
    if not rows:
        return None
    ncols = max(len(r) for r in rows)
    table = document.add_table(rows=0, cols=ncols)
    table.style = "Table Grid"
    table.alignment = WD_ALIGN_PARAGRAPH.CENTER
    for r in rows:
        cells = table.add_row().cells
        for i in range(ncols):
            text = r[i] if i < len(r) else ""
            cell = cells[i]
            cell.text = ""
            cp = cell.paragraphs[0]
            cp.paragraph_format.first_line_indent = Cm(0)
            run = cp.add_run(text)
            run.font.name = "Times New Roman"
            run.font.size = Pt(12)
    return table


# --------------------------------------------------------------------------
# Содержание (поле TOC)
# --------------------------------------------------------------------------
def add_toc(document):
    add_h1(document, "СОДЕРЖАНИЕ")
    note = document.add_paragraph(
        "Обновите поле: правый клик по содержанию → «Обновить поле» / F9."
    )
    note.paragraph_format.first_line_indent = Cm(0)
    for r in note.runs:
        r.font.italic = True
        r.font.size = Pt(12)

    p = document.add_paragraph()
    p.paragraph_format.first_line_indent = Cm(0)
    run = p.add_run()
    fld_begin = OxmlElement("w:fldChar")
    fld_begin.set(qn("w:fldCharType"), "begin")
    instr = OxmlElement("w:instrText")
    instr.set(qn("xml:space"), "preserve")
    instr.text = r'TOC \o "1-3" \h \z \u'
    fld_sep = OxmlElement("w:fldChar")
    fld_sep.set(qn("w:fldCharType"), "separate")
    placeholder = OxmlElement("w:t")
    placeholder.text = "Содержание будет сформировано после обновления поля (F9)."
    fld_end = OxmlElement("w:fldChar")
    fld_end.set(qn("w:fldCharType"), "end")
    run._r.append(fld_begin)
    run._r.append(instr)
    run._r.append(fld_sep)
    run._r.append(placeholder)
    run._r.append(fld_end)


