# Титульный лист
# --------------------------------------------------------------------------
def add_title_page(document):
    def line(text, bold=False, size=14, space=0, align=WD_ALIGN_PARAGRAPH.CENTER):
        p = document.add_paragraph()
        p.alignment = align
        p.paragraph_format.first_line_indent = Cm(0)
        p.paragraph_format.space_after = Pt(space)
        p.paragraph_format.line_spacing_rule = WD_LINE_SPACING.SINGLE
        if text:
            run = p.add_run(text)
            run.font.name = "Times New Roman"
            run.font.size = Pt(size)
            run.font.bold = bold
        return p

    line("АНО ПОО ММКЦТ «Академия ТОП»", bold=True)
    line("________________________________________________")
    line("(полное наименование учебного заведения)")
    line("")
    line("")
    line("")
    line("")
    line("ВЫПУСКНАЯ КВАЛИФИКАЦИОННАЯ РАБОТА", bold=True, size=16)
    line("")
    line("на тему:", size=14)
    line("«Разработка модуля веб-сайта для АНО ПОО ММКЦТ «Академия ТОП»»",
         bold=True, size=14)
    line("")
    line("")
    line("Специальность: ____________________________________")
    line("(код и наименование специальности)")
    line("")
    line("")

    def field(label):
        p = document.add_paragraph()
        p.alignment = WD_ALIGN_PARAGRAPH.LEFT
        p.paragraph_format.first_line_indent = Cm(0)
        p.paragraph_format.line_spacing_rule = WD_LINE_SPACING.SINGLE
        run = p.add_run(label)
        run.font.name = "Times New Roman"
        run.font.size = Pt(14)
