def main():
    document = Document()
    setup_styles(document)
    setup_page(document)

    add_title_page(document)

    build_body(document, ANNOTATION)
    add_page_break(document)

    build_body(document, ABBREVIATIONS)
    add_page_break(document)

    add_toc(document)
    add_page_break(document)

    build_body(document, INTRO)
    add_page_break(document)

    build_body(document, CHAPTER1)
    add_page_break(document)

    build_body(document, CHAPTER2_1)
    build_body(document, CHAPTER2_2)
    build_body(document, CHAPTER2_3)
    build_body(document, CHAPTER2_4)
    add_page_break(document)

    build_body(document, CHAPTER3_1)
    build_body(document, CHAPTER3_2)
    build_body(document, CHAPTER3_3)
    build_body(document, CHAPTER3_4)
    build_body(document, CHAPTER3_5)
    add_page_break(document)

    build_body(document, CHAPTER4)
    add_page_break(document)

    build_body(document, CONCLUSION)
    add_page_break(document)

    build_body(document, REFERENCES)

    for app in APPENDICES:
        add_page_break(document)
        build_body(document, app)

    add_page_number_footer(document)

    document.save(OUTPUT_PATH)
    print("Готово! Файл сохранён:")
    print("    " + OUTPUT_PATH)
    print("")
    print("Дальнейшие шаги:")
